// Extrai e normaliza campos do item Apify Google Maps
const apify = $input.item.json;
const cfg = $('Preparar Config').item.json;

// Telefone limpo
const phone = (apify.phone || apify.phoneUnformatted || '').replace(/\D/g, '');
const website = apify.website || null;
const hasWebsite = !!(website && website.trim());
const hasInstagram = !!(apify.website && apify.website.includes('instagram.com'));
const hasFacebook  = !!(apify.website && apify.website.includes('facebook.com'));

// Nome normalizado para busca CNPJ
const cleanName = (apify.title || '')
  .replace(/\s*(LTDA|ME|EPP|SA|S\.A\.|EIRELI|MEI|SS)\s*\.?$/i, '')
  .replace(/[^a-zA-ZÀ-ÿ0-9\s]/g, ' ').trim().substring(0, 60);

// WhatsApp: presume true se tem telefone (confirmado na Fase 1)
// (validação real via Evolution API fica na Fase 3)
const temWhatsapp = phone.length >= 10 ? true : null;

return [{
  json: {
    apifyData: apify,
    business_name: apify.title || 'Sem nome',
    phone: phone || null,
    website: hasWebsite ? website : null,
    address_full: apify.address || null,
    address_city: apify.city || null,
    address_state: apify.state || cfg.state,
    address_postal_code: apify.postalCode || null,
    google_maps_url: apify.url || null,
    google_rating: parseFloat(apify.totalScore) || null,
    google_reviews_count: parseInt(apify.reviewsCount) || null,
    google_category: apify.categoryName || null,
    has_website: hasWebsite,
    has_instagram: hasInstagram,
    has_facebook: hasFacebook,
    has_google_mybusiness: true,
    tem_whatsapp: temWhatsapp,
    // Para busca CNPJ
    cnpjSearchName: cleanName,
    cnpjSearchCity: apify.city || cfg.city,
    cnpjSearchState: apify.state || cfg.state,
    // Contexto
    oferta: cfg.oferta,
    projectId: $('Salvar Run ID Apify').item.json.projectId,
    apifyRunId: $('Salvar Run ID Apify').item.json.apifyRunId,
    supabaseUrl: $('Salvar Run ID Apify').item.json.supabaseUrl,
    supabaseKey: $('Salvar Run ID Apify').item.json.supabaseKey
  }
}];

// Normaliza resposta da Brasil API para os campos do Supabase
const cnpjData = $input.item.json;
const leadBase = $('Montar Dados Lead').item.json;

const cnpjClean = (cnpjData.cnpj || '').replace(/\.|\/|\-/g, '');

return [{
  json: {
    ...leadBase,
    // CNPJ enriquecido
    cnpj: cnpjClean || null,
    cnpj_razao_social: cnpjData.razao_social || null,
    cnpj_nome_fantasia: cnpjData.nome_fantasia || null,
    cnpj_situacao: cnpjData.descricao_situacao_cadastral || cnpjData.situacao_cadastral || null,
    cnpj_data_abertura: cnpjData.data_inicio_atividade || null,
    cnpj_capital_social: parseFloat(cnpjData.capital_social) || null,
    cnpj_porte: cnpjData.descricao_porte || cnpjData.porte || null,
    cnpj_atividade_principal: cnpjData.cnae_fiscal_descricao || (cnpjData.atividade_principal && cnpjData.atividade_principal[0] && cnpjData.atividade_principal[0].text) || null,
    cnpj_municipio: cnpjData.municipio || null,
    cnpj_uf: cnpjData.uf || null,
    cnpj_email: cnpjData.email || null,
    cnpj_telefone: cnpjData.ddd_telefone_1 || null,
    cnpj_raw: cnpjData,
    // Atualiza email/telefone se veio do CNPJ e não tinha do Google
    email: leadBase.email || cnpjData.email || null,
    phone: leadBase.phone || (cnpjData.ddd_telefone_1 || '').replace(/\D/g,'') || null,
    status: 'ENRIQUECIDO',
    enriched_at: new Date().toISOString()
  }
}];

// Monta o JSON de dados da empresa e constrói o prompt auditável por blocos
const d = $input.item.json;

// Calcula anos de atividade a partir da data de abertura CNPJ
const anosAtividade = d.cnpj_data_abertura
  ? Math.floor((Date.now() - new Date(d.cnpj_data_abertura).getTime()) / (365.25*24*3600*1000))
  : null;

// Estimativa de faturamento baseada em porte e anos
let faturamentoEstimado = 'ausente';
if (d.cnpj_porte && d.cnpj_capital_social) {
  const cap = parseFloat(d.cnpj_capital_social);
  const porte = (d.cnpj_porte || '').toUpperCase();
  if (porte.includes('ME') && cap <= 50000) faturamentoEstimado = `Baixo (capital R$ ${cap.toLocaleString('pt-BR')}, ${porte}, ${anosAtividade||'?'} anos)`;
  else if (porte.includes('ME') || porte.includes('EPP')) faturamentoEstimado = `Médio (capital R$ ${cap.toLocaleString('pt-BR')}, ${porte}, ${anosAtividade||'?'} anos)`;
  else faturamentoEstimado = `Alto (capital R$ ${cap.toLocaleString('pt-BR')}, ${porte}, ${anosAtividade||'?'} anos)`;
}

// JSON de dados da empresa (alimenta a régua de score)
const dadosJson = {
  nome: d.business_name,
  cnpj: d.cnpj || null,
  cidade: (d.address_city || '') + (d.address_state ? '/' + d.address_state : ''),
  site_conteudo: null,   // coletado em versão futura (PageSpeed + scrape)
  tem_whatsapp: d.tem_whatsapp ?? null,
  velocidade_site_segundos: d.site_velocidade_segundos || null,
  nota_google: d.google_rating || null,
  num_avaliacoes: d.google_reviews_count || null,
  instagram_posts_ultimos_30d: d.instagram_posts_30d || null,
  instagram_ultimo_post_dias: d.instagram_ultimo_post_dias || null,
  bio_instagram: d.instagram_bio || null,
  faturamento_estimado_cnpj: faturamentoEstimado,
  anos_de_atividade: anosAtividade
};

const systemPrompt = `Você é o Analista de Qualificação da Hubimobi. Sua função é avaliar UMA empresa por vez a partir de dados públicos e devolver um score auditável.
Você NÃO vende, NÃO escreve mensagem, NÃO inventa dados. Se um dado faltar, registre como ausente — nunca presuma.`;

const nicho = $('Preparar Config').item.json.niche || 'Não informado';
const oferta = d.oferta || $('Preparar Config').item.json.oferta || 'Não informada';

const userPrompt = `NICHO DA CAMPANHA: ${nicho}
OFERTA QUE VAMOS VENDER: ${oferta}

DADOS DA EMPRESA (alguns campos podem vir vazios):
${JSON.stringify(dadosJson, null, 2)}

============================================================
RÉGUA DE SCORE (total 0–100). Pontue CADA bloco de forma independente.
============================================================

BLOCO 1 — CAPACIDADE FINANCEIRA (0–30 pts) — "tem como pagar?"
- Anos de atividade: 5+ anos = 10 | 2–5 = 6 | <2 = 2 | ausente = 4
- Faturamento estimado: alto p/ o nicho = 12 | médio = 8 | baixo = 3 | ausente = 5
- Porte aparente (nº avaliações como proxy de movimento):
  100+ = 8 | 30–100 = 5 | <30 = 2

BLOCO 2 — DOR DIGITAL (0–40 pts) — "precisa do que eu vendo?"
Quanto MAIS dor, MAIS pontos (a dor é o gancho).
- Site: ausente = 12 | existe mas lento (>3s) = 8 | bom = 2
- WhatsApp de atendimento: ausente = 10 | presente sem automação aparente = 5 | presente = 1
- Instagram (frequência): parado 30+ dias = 10 | <2 posts/sem = 6 | ativo = 1
- Reputação: nota boa (4.3+) mas <40 avaliações = 8 | nota baixa = 5 | já tem muitas e boas = 1

BLOCO 3 — ENCAIXE COM A OFERTA (0–30 pts) — "minha oferta resolve a dor dele?"
Avalie se "${oferta}" ataca diretamente as dores que você encontrou.
Conexão direta e óbvia = 30 | parcial = 15 | fraca = 5.
Explique em 1 frase POR QUE deu essa nota.

============================================================
REGRAS DE CLASSIFICAÇÃO
============================================================
- A = 70+   (prospectar)
- B = 45–69 (nutrir depois)
- C = <45   (descartar nesta campanha)
- TRAVA DE SEGURANÇA: se CAPACIDADE FINANCEIRA < 10, rebaixe para no máximo "B".

============================================================
RESPONDA APENAS COM ESTE JSON. Sem markdown, sem texto fora dele.
============================================================
{
  "empresa": "nome",
  "score_capacidade": <0-30>,
  "score_dor": <0-40>,
  "score_encaixe": <0-30>,
  "score_final": <soma>,
  "grade": "A|B|C",
  "rebaixado_por_capacidade": <true|false>,
  "dores": [
    {"dor": "frase curta e concreta", "evidencia": "o dado que comprova", "impacto": "alto|medio|baixo"}
  ],
  "gancho_de_abordagem": "a UMA dor mais forte pra usar no primeiro contato",
  "justificativa_encaixe": "1 frase: por que a oferta resolve (ou não)",
  "dados_ausentes": ["liste o que faltou pra você confiar mais no score"]
}`;

return [{
  json: {
    ...d,
    anosAtividade,
    faturamentoEstimado,
    dadosJson,
    aiSystemPrompt: systemPrompt,
    aiUserPrompt: userPrompt
  }
}];

// Extrai e valida o JSON do novo score auditável por bloco
const apiResponse = $input.item.json;
const leadData = $('Preparar Prompt IA').item.json;

let ai = {};
try {
  const rawText = apiResponse.content?.[0]?.text || '';
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('Sem JSON: ' + rawText.substring(0,120));
  ai = JSON.parse(jsonMatch[0]);
} catch (e) {
  ai = {
    empresa: leadData.business_name,
    score_capacidade: 5, score_dor: 20, score_encaixe: 15, score_final: 40,
    grade: 'B',
    rebaixado_por_capacidade: false,
    dores: [{ dor: 'Análise automática falhou — revisar manualmente', evidencia: e.message, impacto: 'baixo' }],
    gancho_de_abordagem: 'Verificar manualmente',
    justificativa_encaixe: 'Erro de processamento',
    dados_ausentes: ['resposta da IA inválida']
  };
}

// Validação da trava de capacidade (aplicada no cliente como segurança dupla)
let gradeOut = ai.grade || 'B';
if ((ai.score_capacidade || 0) < 10 && gradeOut === 'A') {
  gradeOut = 'B';
  ai.rebaixado_por_capacidade = true;
}

// Tokens e custo (Haiku 4.5: $0.80/M input, $4/M output)
const promptTokens    = apiResponse.usage?.input_tokens  || 0;
const completionTokens = apiResponse.usage?.output_tokens || 0;
const costUsd = (promptTokens * 0.0000008) + (completionTokens * 0.000004);

return [{
  json: {
    ...leadData,
    // Score auditável por bloco
    score: gradeOut,
    score_capacidade: ai.score_capacidade || null,
    score_dor:        ai.score_dor        || null,
    score_encaixe:    ai.score_encaixe    || null,
    score_final:      ai.score_final      || null,
    rebaixado_por_capacidade: !!ai.rebaixado_por_capacidade,
    // Saídas qualitativas
    gancho_de_abordagem:   ai.gancho_de_abordagem   || null,
    justificativa_encaixe: ai.justificativa_encaixe || null,
    dores_estruturadas:    JSON.stringify(ai.dores || []),
    dados_ausentes_ia:     JSON.stringify(ai.dados_ausentes || []),
    // Mantém campos legados compatíveis
    score_rationale:  ai.gancho_de_abordagem || null,
    digital_gap_score: ai.score_dor ? Math.round((ai.score_dor / 40) * 100) : null,
    ai_analysis_raw:  JSON.stringify(ai),
    // IA metadata
    aiPromptTokens:    promptTokens,
    aiCompletionTokens: completionTokens,
    aiCostUsd:         costUsd,
    aiModelUsed:       'claude-haiku-4-5',
    status:            'ANALISADO',
    analyzed_at:       new Date().toISOString()
  }
}];

// Resumo do run para exibição na tela do n8n
const allItems = $input.all();

const summary = {
  mensagem: '✅ Coleta e análise da Fase 1 concluída!',
  timestamp: new Date().toISOString(),
  total_processados: allItems.length,
  dica: 'Acesse a view sdr_validation_panel no Supabase para validar os scores manualmente.',
  proximos_passos: [
    '1. Abra o Supabase → SQL Editor → SELECT * FROM sdr_validation_panel LIMIT 20',
    '2. Valide 20 leads score A manualmente (veja sdr/prompts/analista-sdr.md)',
    '3. Atualize manual_score_ok = true/false em cada lead revisado',
    '4. Se taxa de acerto < 80%, ajuste os critérios no prompt e reanalise'
  ]
};

console.log(JSON.stringify(summary, null, 2));
return [{ json: summary }];
